output_text:
[
  {
    "id": "must_take_cart_from_rack",
    "text": "At the start of a shopping trip, the customer is obliged to take the cart from the entrance rack before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cart_rack_cell": "at(1,5)",
        "cart_available_at_rack": "cartAt(1,5)",
        "at_cart_rack_with_available_cart": {
          "and": [
            "cart_rack_cell",
            "cart_available_at_rack"
          ]
        }
      },
      "events": {
        "pickup_cart_from_rack": {
          "pre": {
            "and": [
              "at_cart_rack_with_available_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_cart_from_rack"
    }
  },
  {
    "id": "must_return_cart_to_top_left_bay",
    "text": "Once a customer has taken a cart, they are obliged to return it to the designated cart bay at the top-left before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from exiting the supermarket while still pushing or holding a shopping cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "only_leave_cart_at_bay",
    "text": "A customer is prohibited from putting down a cart anywhere other than the designated cart bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(0,1)",
        "outside_cart_bay": {
          "not": "cart_bay"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "outside_cart_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_east_from_top_left_with_cart",
    "text": "Moving east from the top-left cart bay is prohibited while still pushing the cart, but is allowed after the cart has been left there.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "east_from_bay_with_cart": {
          "pre": {
            "and": [
              "top_left_cart_bay",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_from_bay_with_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Shelf items must not be carried by hand; item pickups should occur only when the customer has a cart.",
    "abstraction": {
      "state_properties": {
        "hand_occupied": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_occupied",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "no_store_travel_without_cart_before_return",
    "text": "Before the cart has been returned to the cart bay, customers are prohibited from walking around the store without the cart, except for the initial move toward the cart rack.",
    "abstraction": {
      "state_properties": {
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        },
        "without_cart": {
          "not": "hasCart"
        },
        "cart_access_cell": {
          "or": [
            "at(0,5)",
            "at(1,5)"
          ]
        },
        "away_from_cart_access": {
          "not": "cart_access_cell"
        }
      },
      "events": {
        "unauthorized_store_move_without_cart": {
          "pre": {
            "and": [
              "cart_not_returned",
              "without_cart",
              "away_from_cart_access",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "unauthorized_store_move_without_cart"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "After returning the cart to the top-left bay, the customer is obliged to proceed to the exit rather than continue shopping.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        },
        "exit_store": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_to_bay",
      "discharge": "exit_store"
    }
  }
]
